// Hand-written `nestjs-telegraf` stub for the flowatlas fixture suite: the
// decorators the adapter matches on, with the argument types the real package
// declares.
//
// Only the module specifier matters to the adapter, which resolves a decorator
// to its declaration before believing it (D7). That is why the decoy in
// `src/cqrs-like.ts` is declared elsewhere and must be ignored, and why the
// aliased import in `src/checkout.scene.ts` must still be recognised.

/** `string | RegExp`, the two forms a button or a phrase can be matched by. */
export type Trigger = string | RegExp;

export declare const Update: () => ClassDecorator;
export declare const Scene: (id: string) => ClassDecorator;
export declare const Wizard: (id: string) => ClassDecorator;

export declare const Start: () => MethodDecorator;
export declare const Help: () => MethodDecorator;
export declare const Command: (command: string | string[]) => MethodDecorator;
export declare const Action: (triggers: Trigger | Trigger[]) => MethodDecorator;
export declare const On: (updateTypes: string | string[]) => MethodDecorator;
export declare const Hears: (triggers: Trigger | Trigger[]) => MethodDecorator;
export declare const SceneEnter: () => MethodDecorator;
export declare const SceneLeave: () => MethodDecorator;
export declare const WizardStep: (step: number) => MethodDecorator;
